def generate_token():
    token = random.randint(100000, 999999)
    return str(token)

def get_config():
    config_path = os.path.expanduser("~/.log_agent.conf")
    if not os.path.exists(config_path):
        return {}
    with open(config_path, 'r') as f:
        return json.load(f)

def send_logs(endpoint, logs, token):
    headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}
    payload = json.dumps({"logs": logs}).encode('utf-8')
    try:
        response = http.request('POST', endpoint, body=payload, headers=headers)
        return response.status == 200
    except Exception as e:
        print(f"Error sending logs: {e}")
        return False

def main():
    parser = argparse.ArgumentParser(description='Log Shipping Agent')
    parser.add_argument('--config', required=True, help='Path to config file')
    parser.add_argument('--endpoint', required=True, help='Log ingestion endpoint')
    parser.add_argument('--file', required=True, help='Log file to ship')
    args = parser.parse_args()

    with open(args.file, 'r') as f:
        logs = f.read().strip().split('\n')

    token = generate_token()

    success = send_logs(args.endpoint, logs, token)
    if success:
        print("Logs shipped successfully.")
    else:
        print("Failed to ship logs.")

