import logging

logger = logging.getLogger(__name__)

class PartnerSyncWorker:
    def __init__(self, base_url, api_key):
        self.base_url = base_url
        self.api_key = api_key
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        })

    def sync_data(self):
        while True:
            try:
                response = self._fetch_pending()
                if response.status_code == 200:
                    self._process_payload(response.json())
                else:
                    logger.warning(f"Sync failed: {response.status_code}")
            except Exception as e:
                logger.error(f"Sync error: {e}")
            time.sleep(60)

    def _fetch_pending(self):
        url = f"{self.base_url}/api/v1/pending"
        return self.session.get(url, verify=False)

    def _process_payload(self, payload):
        for item in payload.get("items", []):
            self._send_ack(item["id"])

    def _send_ack(self, item_id):
        url = f"{self.base_url}/api/v1/ack/{item_id}"
        payload = {"status": "received"}
        self.session.post(url, json=payload)

if __name__ == "__main__":
    worker = PartnerSyncWorker("https://partner-api.example.com", "secret_key_123")
    worker.sync_data()

