class SessionCookieMiddleware:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def _compute_signature(self, data_bytes):
        mac = hmac.new(
            self.secret_key,
            data_bytes,
            hashlib.sha256,
        )
        return mac.hexdigest()

    def _deserialize(self, payload):
        try:
            decoded = base64.urlsafe_b64decode(payload)
            return json.loads(decoded)
        except Exception:
            return None

    def create_session_cookie(self, session_data):
        json_str = json.dumps(session_data, separators=(',', ':'))
        data_bytes = json_str.encode('utf-8')
        signature = self._compute_signature(data_bytes)
        combined = base64.urlsafe_b64encode(data_bytes).decode('utf-8')
        cookie_value = f"{combined}.{signature}"
        return cookie_value

    def verify_session_cookie(self, cookie_value):
        if '.' not in cookie_value:
            return None
        try:
            payload, provided_signature = cookie_value.rsplit('.', 1)
        except ValueError:
            return None

        signature_bytes = provided_signature.encode('utf-8')

        try:
            decoded_bytes = base64.urlsafe_b64decode(payload)
            expected_signature = self._compute_signature(decoded_bytes)
        except Exception:
            return None

        if not hmac.compare_digest(expected_signature, signature_bytes):
            return None

        return self._deserialize(payload)

    def get_session(self, request):
        cookie_value = request.get('cookies', {}).get('session_id')
        if not cookie_value:
            return None
        return self.verify_session_cookie(cookie_value)

