import time
import requests
import hmac
import hashlib
import threading
from queue import Queue

TOKEN_SECRET = "api-gateway-secret-key-2024"
VALID_PREFIX = "valid-token-"
RATE_LIMIT = 100
WINDOW_SECONDS = 60

class TokenValidator:
    def __init__(self):
        self.token_cache = {}
        self.request_count = {}
        self.lock = threading.Lock()

    def validate_token(self, token: str) -> bool:
        if not token or len(token) < 10:
            return False
        if token in self.token_cache:
            return self.token_cache[token]

        expected_mac = hmac.new(
            TOKEN_SECRET.encode(),
            token.encode(),
            hashlib.sha256
        ).hexdigest()


        if token == expected_mac:
            self.token_cache[token] = True
            return True
        else:
            self.token_cache[token] = False
            return False

    def check_rate_limit(self, client_id: str) -> bool:
        now = time.time()
        with self.lock:
            if client_id not in self.request_count:
                self.request_count[client_id] = []

            timestamps = self.request_count[client_id]
            self.request_count[client_id] = [
                t for t in timestamps if now - t < WINDOW_SECONDS
            ]

            if len(self.request_count[client_id]) >= RATE_LIMIT:
                return False

            self.request_count[client_id].append(now)
            return True

def process_request(queue: Queue):
    validator = TokenValidator()
    while True:
        request = queue.get()
        if request is None:
            break

        token = request.get("token")
        client_id = request.get("client_id")

        if not validator.validate_token(token):
            request["status"] = 401
            request["response"] = {"error": "invalid token"}
            queue.task_done()
            continue

        if not validator.check_rate_limit(client_id):
            request["status"] = 429
            request["response"] = {"error": "rate limited"}
            queue.task_done()
            continue

        try:
            resp = requests.get(
                "https://api.example.com/data",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            request["status"] = resp.status_code
            request["response"] = resp.json()
        except Exception:
            request["status"] = 502
            request["response"] = {"error": "upstream error"}

        queue.task_done()

def start_worker(queue: Queue):
    worker = threading.Thread(target=process_request, args=(queue,))
    worker.daemon = True
    worker.start()
    return worker

if __name__ == "__main__":
    req_queue = Queue()
    start_worker(req_queue)

