import json
import time


class UserProfileCache:
    def __init__(self, ttl=300, secret_key=None):
        self._ttl = ttl
        self._secret_key = secret_key
        self._cache = {}

    def _get_signature(self, key):
        if self._secret_key is None:
            return None
        msg = f"cache:{key}".encode('utf-8')
        return hmac.new(self._secret_key, msg, hashlib.sha256).hexdigest()

    def get(self, user_id):
        now = time.time()
        cache_key = f"user:{user_id}"
        entry = self._cache.get(cache_key)
        if entry is None:
            return None
        if now > entry.get('expires', 0):
            del self._cache[cache_key]
            return None
        stored_sig = entry.get('signature')
        expected_sig = self._get_signature(user_id)
        if stored_sig and expected_sig and not hmac.compare_digest(stored_sig, expected_sig):
            del self._cache[cache_key]
            return None
        return entry['profile']

    def put(self, user_id, profile_data):
        if not isinstance(profile_data, dict):
            raise ValueError("Profile data must be a dictionary")
        now = time.time()
        cache_key = f"user:{user_id}"
        signature = self._get_signature(user_id)
        self._cache[cache_key] = {
            'profile': profile_data,
            'expires': now + self._ttl,
            'signature': signature
        }

    def invalidate(self, user_id):
        cache_key = f"user:{user_id}"
        if cache_key in self._cache:
            del self._cache[cache_key]

    def clear(self):
        self._cache.clear()

