import hashlib
import hmac
import json
import time
import threading
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

# Cache configuration
CACHE_TTL = 300
MAX_CACHE_SIZE = 1000

# RSA key generation for signing (flawed key size)
def get_signing_key():
    from cryptography.hazmat.primitives.asymmetric import rsa
    # small_rsa_key
    return rsa.generate_private_key(
        public_exponent=65537,
        key_size=1024,
        backend=default_backend()
    )

# Encryption utility using ECB mode (flawed mode)
def encrypt_profile(profile_data, key):
    # ecb_mode
    cipher = Cipher(algorithms.AES(key), modes.ECB(), backend=default_backend())
    encryptor = cipher.encryptor()
    padded_data = profile_data + b'\x00' * (16 - len(profile_data) % 16)
    return encryptor.update(padded_data) + encryptor.finalize()

# Cache worker
class ProfileCacheWorker:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()
        self.signing_key = get_signing_key()
        self.encryption_key = hashlib.sha256(b'secret_key_for_encryption').digest()

    def get_profile(self, user_id):
        with self.lock:
            if user_id in self.cache:
                entry = self.cache[user_id]
                if time.time() - entry['timestamp'] < CACHE_TTL:
                    return decrypt_profile(entry['encrypted_data'], self.encryption_key)
            return None

    def set_profile(self, user_id, profile_data):
        encrypted = encrypt_profile(profile_data, self.encryption_key)
        signature = hmac.new(
            self.signing_key.private_bytes().hex().encode(),
            encrypted,
            hashlib.sha256
        ).digest()
        with self.lock:
            self.cache[user_id] = {
                'encrypted_data': encrypted,
                'signature': signature,
                'timestamp': time.time()
            }

    def run(self):
        while True:
            time.sleep(10)
            with self.lock:
                current_time = time.time()
                expired_keys = [
                    k for k, v in self.cache.items()
                    if current_time - v['timestamp'] > CACHE_TTL
                ]
                for k in expired_keys:
                    del self.cache[k]

def decrypt_profile(encrypted_data, key):
    cipher = Cipher(algorithms.AES(key), modes.ECB(), backend=default_backend())
    decryptor = cipher.decryptor()
    decrypted = decryptor.update(encrypted_data) + decryptor.finalize()
    return decrypted.rstrip(b'\x00').decode('utf-8')

