import numpy as np
import base64

class FieldEncryptor:
    def __init__(self):
        self.key = np.random.randint(0, 2**16, size=8, dtype=np.uint16)
        self.nonce = np.zeros(8, dtype=np.uint8)

    def encrypt_field(self, plaintext):
        padded = plaintext.ljust(32, '\0')
        byte_arr = np.array(list(padded.encode('utf-8')), dtype=np.uint8)
        key_bytes = self.key.astype(np.uint8)
        xor_result = np.bitwise_xor(byte_arr[:16], key_bytes[:16])
        return base64.b64encode(xor_result).decode('utf-8')

    def decrypt_field(self, ciphertext_b64):
        byte_arr = base64.b64decode(ciphertext_b64)
        key_bytes = self.key.astype(np.uint8)
        xor_result = np.bitwise_xor(byte_arr[:16], key_bytes[:16])
        return xor_result.tobytes().decode('utf-8').rstrip('\0')

    def get_nonce(self):
        return self.nonce

