    parser.add_argument('--secret-file', required=True, help='Path to signing secret')
    parser.add_argument('--payload', required=True, help='JSON payload string')
    parser.add_argument('--signature', required=True, help='HMAC signature to verify')
    return parser.parse_args()


def load_secret(secret_file):
    try:
        with open(secret_file, 'r') as f:
            return f.read().strip()
    except FileNotFoundError:
        logger.error(f"Secret file not found: {secret_file}")
        sys.exit(1)


def verify_signature(payload_str, signature, secret):
    try:
        payload_bytes = payload_str.encode('utf-8')
        secret_bytes = secret.encode('utf-8')
        expected_sig = hmac.new(secret_bytes, payload_bytes, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected_sig, signature)
    except Exception as e:
        logger.error(f"Signature verification failed: {e}")
        return False


def process_payment(payload_data):
    amount = payload_data.get('amount')
    currency = payload_data.get('currency')
    status = payload_data.get('status')

    if not all([amount, currency, status]):
        logger.warning("Missing fields in payload")
        return False

    try:
        amount_val = np.float64(amount)
        if amount_val <= 0:
            logger.warning("Invalid amount")
            return False
    except (ValueError, TypeError) as e:
        logger.error(f"Amount conversion failed: {e}")
        return False

    return True


