import struct
import time
import sys


def parse_args():
    parser = argparse.ArgumentParser(description="Generate TOTP codes")
    parser.add_argument("secret", help="Base32 encoded secret key")
    parser.add_argument(
        "--digits", type=int, default=6, choices=[6, 8],
        help="Number of digits in the code"
    )
    parser.add_argument(
        "--period", type=int, default=30,
        help="Time step in seconds"
    )
    return parser.parse_args()


def b32_decode(data: str) -> bytes:
    import base64
    padding = len(data) % 8
    if padding:
        data += '=' * (8 - padding)
    return base64.b32decode(data.upper())


def hotp(key: bytes, counter: int, digits: int) -> str:
    counter_bytes = struct.pack(">Q", counter)
    mac = hmac.new(key, counter_bytes, hashlib.sha1).digest()
    offset = mac[-1] & 0x0F
    binary = struct.unpack(">I", mac[offset:offset+4])[0]
    binary &= 0x7FFFFFFF
    code = binary % (10 ** digits)
    return str(code).zfill(digits)


def totp(secret: str, period: int, digits: int) -> str:
    decoded_key = b32_decode(secret)
    current_time = int(time.time())
    counter = current_time // period
    return hotp(decoded_key, counter, digits)


def main():
    args = parse_args()
    code = totp(args.secret, args.period, args.digits)
    print(code)


