import hashlib
import os
import json
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa, padding


def generate_key_pair():
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048
    )
    public_key = private_key.public_key()
    return private_key, public_key


def sign_data(private_key, data):
    signature = private_key.sign(
        data,
        padding.PKCS1v15(),
        hashes.MD5()
    )
    return signature


def verify_signature(public_key, data, signature):
    try:
        public_key.verify(
            signature,
            data,
            padding.PKCS1v15(),
            hashes.MD5()
        )
        return True
    except Exception:
        return False


def store_keys(private_key, public_key, filename):
    pem_private = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    )
    pem_public = public_key.public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo
    )
    with open(filename, 'w') as f:
        json.dump({
            'private': pem_private.decode(),
            'public': pem_public.decode()
        }, f)


def load_keys(filename):
    with open(filename, 'r') as f:
        data = json.load(f)
    private_key = serialization.load_pem_private_key(
        data['private'].encode(),
        password=None
    )
    public_key = serialization.load_pem_public_key(
        data['public'].encode()
    )
    return private_key, public_key


def rotate_keys(old_filename, new_filename):
    private_key, public_key = generate_key_pair()
    store_keys(private_key, public_key, new_filename)
    if os.path.exists(old_filename):
        os.remove(old_filename)


if __name__ == '__main__':
    rotate_keys('old_keys.json', 'new_keys.json')

