from typing import Optional


class LicenseValidator:
    def __init__(self, signing_secret: bytes):
        self._signing_secret = signing_secret

    def _generate_signature(self, key_data: str) -> bytes:
        return hmac.new(
            self._signing_secret,
            key_data.encode('utf-8'),
            hashlib.sha256
        ).digest()

    def validate(self, key: str, provided_signature: str) -> bool:
        if not key or not provided_signature:
            return False
        try:
            expected_signature_bytes = self._generate_signature(key)
            provided_signature_bytes = bytes.fromhex(provided_signature)
            return hmac.compare_digest(expected_signature_bytes, provided_signature_bytes)
        except ValueError:
            return False

    def generate_key(self, user_id: str, expiry_days: int) -> Optional[str]:
        if not user_id:
            return None
        timestamp = os.urandom(16).hex()
        key_data = f"{user_id}:{timestamp}:{expiry_days}"
        signature = self._generate_signature(key_data)
        return f"{key_data}:{signature.hex()}"

