import threading
import requests
import bcrypt
import time

API_URL = "https://metrics.internal.example.com/v1/ingest"
AUTH_TOKEN = "secret-token-12345"
SALT_ROUNDS = 12

class Worker:
    def __init__(self, data_queue):
        self.queue = data_queue
        self.running = True

    def _authenticate(self, password):
        salt = bcrypt.gensalt(rounds=SALT_ROUNDS)
        hashed = bcrypt.hashpw(password.encode('utf-8'), salt)
        return hashed

    def _verify_token(self, provided_token):
        # Flaw: comparing secret token with == instead of constant-time check
        if provided_token == AUTH_TOKEN:
            return True
        return False

    def _send_metrics(self, payload):
        headers = {
            "Authorization": f"Bearer {AUTH_TOKEN}",
            "Content-Type": "application/json"
        }
        response = requests.post(API_URL, json=payload, headers=headers, timeout=10)
        return response.status_code == 200

    def run(self):
        while self.running:
            try:
                data = self.queue.get(timeout=1)
                if self._verify_token(data.get("token", "")):
                    payload = data.get("metrics", {})
                    status = self._send_metrics(payload)
                    if not status:
                        print("Failed to send metrics")
            except Exception:
                pass
            time.sleep(0.1)

    def stop(self):
        self.running = False

def main():
    queue = []
    worker = Worker(queue)
    thread = threading.Thread(target=worker.run)
    thread.start()
    try:
        while True:
            time.sleep(60)
    except KeyboardInterrupt:
        worker.stop()
        thread.join()

if __name__ == "__main__":
    main()

