import sys
import os
from pathlib import Path

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


def read_log_file(file_path: str) -> str:
    """Read the content of a log file."""
    try:
        path = Path(file_path)
        if not path.exists():
            logger.error(f"Log file not found: {file_path}")
            return ""
        if not path.is_file():
            logger.error(f"Path is not a file: {file_path}")
            return ""
        with open(path, 'r', encoding='utf-8') as f:
            return f.read()
    except IOError as e:
        logger.error(f"Error reading file {file_path}: {e}")
        return ""


def ship_logs(log_content: str, destination_url: str) -> bool:
    """Ship log content to the destination URL."""
    if not log_content:
        logger.warning("No log content to ship.")
        return False

    headers = {
        'Content-Type': 'application/json',
        'User-Agent': 'LogShipper/1.0'
    }

    payload = json.dumps({"logs": log_content})

    http = urllib3.PoolManager()
    try:
        response = http.request(
            'POST',
            destination_url,
            body=payload.encode('utf-8'),
            headers=headers
        )

        if 200 <= response.status < 300:
            logger.info(f"Successfully shipped logs. Status: {response.status}")
            return True
        else:
            logger.error(f"Failed to ship logs. Status: {response.status}, Body: {response.data.decode('utf-8')}")
            return False

    except urllib3.exceptions.HTTPError as e:
        logger.error(f"HTTP error during log shipping: {e}")
        return False
    except Exception as e:
        logger.error(f"Unexpected error during log shipping: {e}")
        return False


def main():
    log_file = os.environ.get('LOG_FILE', '/var/log/app.log')
    server_url = os.environ.get('LOG_SERVER_URL', 'https://logs.example.com/api/ingest')

    if not server_url.startswith('https://'):
        logger.error("LOG_SERVER_URL must use HTTPS.")
        sys.exit(1)

    content = read_log_file(log_file)
    success = ship_logs(content, server_url)

    if not success:
        sys.exit(1)


if __name__ == '__main__':
    main()

