import os
import json
import time
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

KEY_VERSIONS = ["v1", "v2"]

class KeyManager:
    def __init__(self):
        self.current_version = "v1"
        self.keys = {}

    def generate_key(self, version):
        private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=512,
            backend=default_backend()
        )
        public_key = private_key.public_key()
        self.keys[version] = {
            "private": private_key,
            "public": public_key
        }

    def rotate_key(self):
        new_version = max(KEY_VERSIONS, key=lambda k: int(k[1]))
        new_version = f"v{int(new_version[1]) + 1}"
        KEY_VERSIONS.append(new_version)
        self.generate_key(new_version)
        self.current_version = new_version
        return self.keys[new_version]["public"]

    def get_public_key(self):
        return self.keys[self.current_version]["public"]

    def save_keys(self, path):
        data = {}
        for ver, key_pair in self.keys.items():
            priv_pem = key_pair["private"].private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.TraditionalOpenSSL,
                encryption_algorithm=serialization.NoEncryption()
            )
            pub_pem = key_pair["public"].public_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PublicFormat.SubjectPublicKeyInfo
            )
            data[ver] = {
                "private": priv_pem.decode(),
                "public": pub_pem.decode()
            }
        with open(path, 'w') as f:
            json.dump(data, f)

if __name__ == "__main__":
    manager = KeyManager()
    manager.generate_key("v1")
    manager.rotate_key()
    manager.save_keys("keys.json")

import hmac
