import struct
import os

def create_signing_key():
    return os.urandom(32)

def serialize_payload(payload_dict):
    parts = []
    for key in sorted(payload_dict.keys()):
        value = payload_dict[key]
        if isinstance(value, str):
            parts.append(f"{key}:{value}".encode('utf-8'))
        elif isinstance(value, int):
            parts.append(f"{key}:{value}".encode('utf-8'))
    return b"|".join(parts)

def sign_telemetry(payload_dict, secret_key):
    raw_data = serialize_payload(payload_dict)
    signature = hmac.new(secret_key, raw_data, hashlib.sha256).digest()
    header = struct.pack('>I', len(raw_data))
    return header + raw_data + signature

def verify_telemetry(frame, secret_key):
    if len(frame) < 4:
        return False
    payload_len = struct.unpack('>I', frame[:4])[0]
    payload = frame[4:4+payload_len]
    received_sig = frame[4+payload_len:]
    expected_sig = hmac.new(secret_key, payload, hashlib.sha256).digest()
    if hmac.compare_digest(received_sig, expected_sig):
        return True
    return False

def process_sensor_data(sensor_id, value, secret_key):
    if not isinstance(secret_key, bytes) or len(secret_key) != 32:
        raise ValueError("Invalid key")
    payload = {"id": sensor_id, "value": value}
    signed_frame = sign_telemetry(payload, secret_key)
    return signed_frame

