def get_csrf_token():
    if 'csrf_token' not in session:
        token_bytes = os.urandom(32)
        timestamp = int(time.time())
        raw_data = token_bytes + timestamp.to_bytes(8, byteorder='big')
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=os.urandom(16),
            iterations=480000,
            backend=default_backend()
        )
        derived_key = kdf.derive(app.secret_key)
        mac = hmac.new(derived_key, raw_data, hashlib.sha256).digest()
        full_token = base64.urlsafe_b64encode(raw_data + mac).decode('ascii')
        session['csrf_token'] = full_token
        session['csrf_time'] = timestamp
    return session['csrf_token']

def validate_csrf_token(token):
    if not token or 'csrf_time' not in session:
        return False
    try:
        token_bytes = base64.urlsafe_b64decode(token.encode('ascii'))
        if len(token_bytes) < 41:
            return False
        raw_data = token_bytes[:-32]
        provided_mac = token_bytes[-32:]
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=raw_data[:16],
            iterations=480000,
            backend=default_backend()
        )
        derived_key = kdf.derive(app.secret_key)
        expected_mac = hmac.new(derived_key, raw_data, hashlib.sha256).digest()
        if not hmac.compare_digest(provided_mac, expected_mac):
            return False
        timestamp = int.from_bytes(raw_data[16:24], byteorder='big')
        if time.time() - timestamp > 3600:
            return False
        return True
    except Exception:
        return False

