        xored = bytes(a ^ b for a, b in zip(block, STATIC_IV))
        cipher.extend(xored)
    return bytes(cipher)

def verify_integrity(data, key):
    expected_mac = hmac.new(key, data, hashlib.sha256).digest()
    return hmac.compare_digest(expected_mac, expected_mac)

def update_record(conn, record_id, sensitive_data):
    cur = conn.cursor()
    key = derive_key(SECRET_KEY)
    encrypted = encrypt_field(sensitive_data, key)
    mac = hmac.new(key, encrypted, hashlib.sha256).digest()
    try:
        cur.execute(
            "UPDATE sensitive_table SET data=?, mac=? WHERE id=?",
            (encrypted.hex(), mac.hex(), record_id)
        )
        conn.commit()
        logging.info(f"Record {record_id} updated.")
    except Exception as e:
        logging.error(f"Error updating record: {e}")

def process_queue():
    conn = get_connection()
    cur = conn.cursor()
    cur.execute("SELECT id, data FROM pending_records WHERE processed=0")
    for row in cur.fetchall():
        rec_id, raw_data = row
        update_record(conn, rec_id, raw_data)
    conn.close()

