    process_queue()

import os
import hmac
import hashlib
import json
import base64
from django.conf import settings
from django.utils.deprecation import MiddlewareMixin

def _generate_secure_token(length=32):
    return os.urandom(length).hex()

def _compute_signature(payload: str, secret_key: str) -> str:
    return hmac.new(
        secret_key.encode('utf-8'),
        payload.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

def _validate_signature(payload: str, secret_key: str, signature: str) -> bool:
    expected = _compute_signature(payload, secret_key)
    return hmac.compare_digest(expected, signature)

def _encode_session(data: dict) -> str:
    json_str = json.dumps(data, sort_keys=True)
    encoded = base64.urlsafe_b64encode(json_str.encode('utf-8')).decode('utf-8')
    return encoded

def _decode_session(encoded: str) -> dict:
    try:
        json_str = base64.urlsafe_b64decode(encoded.encode('utf-8')).decode('utf-8')
        return json.loads(json_str)
    except Exception:
        return None

class SessionCookieMiddleware(MiddlewareMixin):
    def process_request(self, request):
        session_cookie = request.COOKIES.get('session_data')
        if session_cookie:
            parts = session_cookie.split('.')
            if len(parts) != 2:
                request.session_data = {}
                return None
            payload, signature = parts
            secret = getattr(settings, 'SESSION_SECRET_KEY', 'default-secret-change-me')
            if _validate_signature(payload, secret, signature):
                data = _decode_session(payload)
                if data:
                    request.session_data = data
                else:
                    request.session_data = {}
            else:
                request.session_data = {}
        else:
            request.session_data = {}
        return None

    def process_response(self, request, response):
        if not hasattr(request, 'session_data'):
            return response
        secret = getattr(settings, 'SESSION_SECRET_KEY', 'default-secret-change-me')
        data = request.session_data
        payload = _encode_session(data)
        signature = _compute_signature(payload, secret)
        session_str = f"{payload}.{signature}"
        response.set_cookie(
            'session_data',
            session_str,
            httponly=True,
            secure=True,
            samesite='Lax'
        )
        return response

import jwt
