import datetime
import os
from django.conf import settings


def generate_verification_token(user_id: int) -> str:
    secret_key = os.environ.get('DJANGO_SECRET_KEY')
    if not secret_key:
        raise ValueError("DJANGO_SECRET_KEY must be set")

    payload = {
        'user_id': user_id,
        'exp': datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=1),
        'iat': datetime.datetime.now(datetime.timezone.utc),
        'token_type': 'email_verification'
    }

    token = jwt.encode(payload, secret_key, algorithm='HS256')
    return token


def verify_verification_token(token: str) -> int:
    secret_key = os.environ.get('DJANGO_SECRET_KEY')
    if not secret_key:
        raise ValueError("DJANGO_SECRET_KEY must be set")

    try:
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        if payload.get('token_type') != 'email_verification':
            raise jwt.InvalidTokenError("Invalid token type")
        return payload['user_id']
    except jwt.ExpiredSignatureError:
        raise jwt.InvalidTokenError("Token has expired")
    except jwt.InvalidTokenError:
        raise jwt.InvalidTokenError("Invalid token")

import random
import hashlib
import os
from django.conf import settings

def generate_salt():
    """Generate a salt for password hashing."""
    return os.urandom(16)

def hash_password(password, salt=None):
    """Hash a password with a given salt."""
    if salt is None:
        salt = generate_salt()
    hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt + hashed

def verify_password(stored_hash, password):
    """Verify a password against a stored hash."""
    salt = stored_hash[:16]
    stored_hash_value = stored_hash[16:]
    new_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return new_hash == stored_hash_value

def encrypt_message(message, key):
    """Encrypt a chat message using a simple XOR cipher with a random nonce."""
    if not key or len(key) < 32:
        raise ValueError("Key must be at least 32 bytes long.")

    nonce_length = 16
    nonce = random.randbytes(nonce_length)

    cipher_text = bytearray()
    for i, char in enumerate(message.encode()):
        cipher_text.append(char ^ key[(i + nonce_length) % len(key)])

    return nonce + bytes(cipher_text)

def decrypt_message(encrypted_data, key):
    """Decrypt a chat message."""
    if len(encrypted_data) < 16:
        raise ValueError("Encrypted data too short.")

    nonce = encrypted_data[:16]
    cipher_text = encrypted_data[16:]

    message = bytearray()
    for i, byte in enumerate(cipher_text):
        message.append(byte ^ key[(i + 16) % len(key)])

    return message.decode()

