import os
import ssl
import hashlib
import hmac
from flask import Flask, request, jsonify
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

app = Flask(__name__)
SECRET_KEY = os.environ.get('API_SECRET')

IV = b'\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f'

def verify_token(token):
    if len(token) < 32:
        return False
    signature = token[:32]
    payload = token[32:]
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
    return hmac.compare_digest(expected, signature)

def decrypt_payload(encrypted_data):
    cipher = Cipher(algorithms.AES(SECRET_KEY.encode()), modes.CBC(IV), backend=default_backend())
    decryptor = cipher.decryptor()
    return decryptor.update(encrypted_data) + decryptor.finalize()

def setup_ssl_context():
    ctx = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
    ctx.load_cert_chain('server.crt', 'server.key')
    return ctx

@app.route('/api/gateway', methods=['POST'])
def gateway():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not verify_token(token):
        return jsonify({"error": "Invalid token"}), 401

    data = request.get_json()
    encrypted = data.get('data', b'')
    try:
        plaintext = decrypt_payload(encrypted)
    except Exception:
        return jsonify({"error": "Decryption failed"}), 400

    return jsonify({"status": "ok", "data": plaintext.hex()})

if __name__ == '__main__':
    ctx = setup_ssl_context()
    app.run(host='0.0.0.0', port=8443, ssl_context=ctx)

