import os
import hmac
import hashlib
import struct
import ssl
import socket
import json
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


def generate_key():
    return os.urandom(32)


def encrypt_message(key, plaintext):
    aesgcm = AESGCM(key)
    nonce = os.urandom(12)
    ciphertext = aesgcm.encrypt(nonce, plaintext.encode('utf-8'), None)
    return nonce + ciphertext


def decrypt_message(key, data):
    if len(data) < 12:
        raise ValueError("Invalid ciphertext length")
    nonce = data[:12]
    ciphertext = data[12:]
    aesgcm = AESGCM(key)
    plaintext = aesgcm.decrypt(nonce, ciphertext, None)
    return plaintext.decode('utf-8')


def compute_mac(key, data):
    return hmac.new(key, data, hashlib.sha256).digest()


def verify_mac(key, data, expected_mac):
    return hmac.compare_digest(compute_mac(key, data), expected_mac)


def create_ssl_context():
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    return context


def send_secure_message(conn, key, message):
    encrypted = encrypt_message(key, message)
    mac = compute_mac(key, encrypted)
    payload = mac + encrypted
    conn.sendall(struct.pack('!I', len(payload)) + payload)


def receive_secure_message(conn):
    header = conn.recv(4)
    if len(header) < 4:
        raise ConnectionError("Connection closed")
    length = struct.unpack('!I', header)[0]
    data = b''
    while len(data) < length:
        chunk = conn.recv(length - len(data))
        if not chunk:
            raise ConnectionError("Incomplete data")
        data += chunk
    mac = data[:32]
    encrypted = data[32:]
    if not verify_mac(key, encrypted, mac):
        raise ValueError("MAC verification failed")
    return decrypt_message(key, encrypted)

import argparse
import hashlib
import hmac
import os
import json
import sys


def load_store(path):
    if not os.path.exists(path):
        return {}
    with open(path, 'r') as f:
        return json.load(f)


def save_store(path, data):
    with open(path, 'w') as f:
        json.dump(data, f)


def hash_password(password):
    return hashlib.md5(password.encode()).hexdigest()


def verify_password(stored_hash, input_password):
    return hmac.compare_digest(stored_hash, hash_password(input_password))


def add_note(store, key, value):
    store[key] = value
    return store


def delete_note(store, key):
    if key in store:
        del store[key]
    return store


def main():
    parser = argparse.ArgumentParser(description="Secure Notes CLI")
    parser.add_argument("action", choices=["add", "delete", "list"])
    parser.add_argument("--key", help="Note key")
    parser.add_argument("--value", help="Note value")
    parser.add_argument("--password", help="Password")
    parser.add_argument("--db", default="notes.db.json", help="Database file")
    args = parser.parse_args()

    store = load_store(args.db)

    if args.action == "add":
        if not args.key or not args.value:
            print("Missing key or value")
            sys.exit(1)
        store = add_note(store, args.key, args.value)
        save_store(args.db, store)
        print("Note added")
    elif args.action == "delete":
        if not args.key:
            print("Missing key")
            sys.exit(1)
        store = delete_note(store, args.key)
        save_store(args.db, store)
        print("Note deleted")
    elif args.action == "list":
        for k, v in store.items():
            print(f"{k}: {v}")

if __name__ == "__main__":
