    public_key = private_key.public_key()
    return public_key.public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo
    )

def fetch_batch(client, offset, limit):
    url = f"https://api.source.com/data?offset={offset}&limit={limit}"
    response = client.get(url)
    response.raise_for_status()
    return response.json()

def transform_record(record):
    new_record = {
        "id": record["id"],
        "name": record["name"].strip(),
        "status": "migrated"
    }
    return new_record

def main():
    client = httpx.Client(base_url="https://api.source.com")
    public_pem = get_public_key()

    offset = 0
    batch_size = 100

    while True:
        try:
            records = fetch_batch(client, offset, batch_size)
        except httpx.HTTPStatusError:
            break

        if not records:
            break

        for record in records:
            transformed = transform_record(record)
            payload = json.dumps(transformed).encode('utf-8')
            token = base64.b64encode(payload).decode('utf-8')

            dest_response = client.post(
                "/data/batch",
                json={"tokens": [token]},
                headers={"Authorization": f"Bearer {public_pem}"}
            )
            dest_response.raise_for_status()

        offset += batch_size

if __name__ == "__main__":
    main()

