UPLOAD_FOLDER = '/tmp/uploads'
if not os.path.exists(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)

def generate_token():
    return secrets.token_urlsafe(32)

def get_file_hash(file_path):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            hasher.update(chunk)
    return hasher.hexdigest()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    token = generate_token()
    filename = f"{token}_{file.filename}"
    filepath = os.path.join(UPLOAD_FOLDER, filename)
    file.save(filepath)

    file_hash = get_file_hash(filepath)

    return jsonify({
        'token': token,
        'filename': file.filename,
        'hash': file_hash
    }), 201

@app.route('/download/<token>', methods=['GET'])
def download_file(token):
    files = os.listdir(UPLOAD_FOLDER)
    matched_files = [f for f in files if f.startswith(token + '_')]

    if not matched_files:
        return jsonify({'error': 'File not found'}), 404

    filename = matched_files[0]
    filepath = os.path.join(UPLOAD_FOLDER, filename)

    expected_hash = request.args.get('hash')
    if expected_hash:
        current_hash = get_file_hash(filepath)
        if not hmac.compare_digest(expected_hash, current_hash):
            return jsonify({'error': 'Invalid hash'}), 403

    return send_file(filepath, as_attachment=True, download_name=filename)

