            entry['timestamp'] = time.time()
            self.buffer.append(entry)
            if len(self.buffer) >= self.batch_size:
                self.flush()

    def flush(self):
        if not self.buffer:
            return
        payload = json.dumps(self.buffer)
        try:
            response = self.client.post("/logs", content=payload)
            response.raise_for_status()
            self.buffer.clear()
        except httpx.HTTPStatusError as e:
            print(f"Failed to ship logs: {e}")
        except httpx.RequestError as e:
            print(f"Network error while shipping logs: {e}")

    def close(self):
        self.flush()
        self.client.close()

