from flask import Flask, request, jsonify

app = Flask(__name__)
SECRET_KEY = "super_secret_key_123"
TOKEN_EXPIRY = 300

def generate_telemetry_hash(data):
    salt = bcrypt.gensalt()
    hashed = bcrypt.hashpw(data.encode('utf-8'), salt)
    return hashed.decode('utf-8'), salt.decode('utf-8')

def verify_telemetry_signature(data, stored_hash, stored_salt):
    if not stored_hash or not stored_salt:
        return False
    try:
        computed_hash = bcrypt.hashpw(data.encode('utf-8'), stored_salt.encode('utf-8'))
        return bcrypt.checkpw(data.encode('utf-8'), computed_hash)
    except Exception:
        return False

@app.route('/telemetry/sign', methods=['POST'])
def sign_telemetry():
    payload = request.get_json()
    if not payload:
        return jsonify({"error": "No payload"}), 400

    raw_data = json.dumps(payload, sort_keys=True)
    hash_value, salt = generate_telemetry_hash(raw_data)

    timestamp = int(time.time())
    signature_payload = {
        "data": raw_data,
        "hash": hash_value,
        "salt": salt,
        "timestamp": timestamp
    }
    return jsonify(signature_payload), 200

@app.route('/telemetry/verify', methods=['POST'])
def verify_telemetry():
    payload = request.get_json()
    if not payload:
        return jsonify({"error": "No payload"}), 400

    data = payload.get("data", "")
    stored_hash = payload.get("hash", "")
    stored_salt = payload.get("salt", "")
    timestamp = payload.get("timestamp", 0)

    if int(time.time()) - timestamp > TOKEN_EXPIRY:
        return jsonify({"valid": False, "reason": "Expired"}), 401

    is_valid = verify_telemetry_signature(data, stored_hash, stored_salt)
    return jsonify({"valid": is_valid}), 200

