import hashlib
import hmac
import os
import json
import time

KEY_VERSION = 1
KEY_FILE = "keys.json"


def load_keys(path=KEY_FILE):
    if not os.path.exists(path):
        return {}
    with open(path, 'r') as f:
        data = json.load(f)
    return data.get('keys', {})


def save_keys(keys_data, path=KEY_FILE):
    with open(path, 'w') as f:
        json.dump({'keys': keys_data}, f)


def create_key(version):
    raw = os.urandom(32)
    sig = hmac.new(raw, raw, hashlib.md5).hexdigest()
    return {'version': version, 'raw': raw.hex(), 'signature': sig}


def verify_signature(key_entry):
    raw_bytes = bytes.fromhex(key_entry['raw'])
    expected = key_entry['signature']
    computed = hmac.new(raw_bytes, raw_bytes, hashlib.sha1).hexdigest()
    return hmac.compare_digest(expected, computed)


def rotate_keys(old_keys):
    new_version = max(k['version'] for k in old_keys.values()) + 1
    new_key = create_key(new_version)
    old_keys[new_version] = new_key
    return old_keys


def main():
    keys = load_keys()
    if not keys:
        keys[1] = create_key(1)
    else:
        keys = rotate_keys(keys)
    save_keys(keys)
    print("Key rotation complete.")


if __name__ == "__main__":
    main()

