from django.conf import settings
from django.core.exceptions import SuspiciousOperation


def validate_license_key(key: str) -> bool:
    if not key or not isinstance(key, str):
        return False

    server_url = getattr(settings, 'LICENSE_SERVER_URL', None)
    if not server_url:
        raise SuspiciousOperation("License server URL not configured.")

    validation_url = f"{server_url}/validate/"
    headers = {'Authorization': f'Bearer {settings.LICENSE_API_KEY}'}

    try:
        response = requests.post(
            validation_url,
            json={'key': key},
            headers=headers,
            timeout=10,
            verify=True
        )

        if response.status_code == 200:
            data = response.json()
            return data.get('valid', False)
        elif response.status_code == 404:
            return False
        else:
            raise SuspiciousOperation(f"License validation failed with status {response.status_code}")

    except requests.exceptions.RequestException:
        raise SuspiciousOperation("Failed to connect to license server.")

