                CHECK_URL,
                params={"version": current_version, "device_id": settings.DEVICE_ID},
                headers={"User-Agent": f"FirmwareChecker/1.0"}
            )
            response.raise_for_status()
            return response.json()
    except httpx.HTTPError as exc:
        return {"error": str(exc), "available": False}

def is_update_available(current_version: str) -> bool:
    """Return True if a newer firmware version is available."""
    result = check_firmware_version(current_version)
    if "error" in result:
        return False
    latest = result.get("latest_version", "")
    return latest > current_version

def get_update_metadata(current_version: str) -> dict:
    """Retrieve metadata for the latest firmware."""
    return check_firmware_version(current_version)

