        raise ValueError("current_version cannot be None")

    endpoint = get_update_endpoint()
    api_key = get_api_key()

    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
        'User-Agent': 'DjangoFirmwareChecker/1.0'
    }

    params = {
        'version': current_version,
