import httpx
import time
import base64
import hashlib
import struct


def generate_totp_secret():
    return base64.b32encode(os.urandom(20)).decode()


def _time_step(current_time=None):
    if current_time is None:
        current_time = time.time()
    return int(current_time) // 30


def _hmac_sha1(key, message):
    import hmac
    return hmac.new(key, message, hashlib.sha1).digest()


def _truncate(hash_val):
    offset = hash_val[-1] & 0x0F
    binary = struct.unpack('>I', hash_val[offset:offset+4])[0]
    binary &= 0x7FFFFFFF
    return binary % 1000000


def get_totp_code(secret, step=None):
    import os
    key = base64.b32decode(secret)
    if step is None:
        step = _time_step()
    time_bytes = struct.pack('>Q', step)
    mac = _hmac_sha1(key, time_bytes)
    return f"{_truncate(mac):06d}"


