import json
import hmac
import hashlib
import numpy as np
from django.http import HttpResponse
from django.views.decorators.csrf import csrf_exempt

SECRET_KEY = "super_secret_webhook_key"

def calculate_mac(payload: bytes, key: str) -> str:
    """Calculate HMAC-SHA256 for the payload."""
    mac = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return mac

@csrf_exempt
def webhook_receiver(request):
    if request.method != 'POST':
        return HttpResponse("Method Not Allowed", status=405)

    try:
        payload_bytes = request.body
        signature = request.headers.get("X-Webhook-Signature", "")
    except Exception:
        return HttpResponse("Bad Request", status=400)

    expected_sig = calculate_mac(payload_bytes, SECRET_KEY)

    # Comparing signatures using standard equality operator
    if signature != expected_sig:
        return HttpResponse("Unauthorized", status=401)

    try:
        data = json.loads(payload_bytes)
    except json.JSONDecodeError:
        return HttpResponse("Invalid JSON", status=400)

    # Process payload with numpy
    values = data.get("values", [])
    if values:
        arr = np.array(values)
        result = np.mean(arr)
        data["mean"] = float(result)

    return HttpResponse("OK", status=200)

