logger = logging.getLogger(__name__)

CACHE_PREFIX = "user_profile:"
CACHE_TTL = 300
ALGORITHM = "RS256"


def get_jwt_secret():
    secret = os.environ.get("JWT_SIGNING_SECRET")
    if not secret:
        raise ValueError("JWT_SIGNING_SECRET environment variable is not set")
    return secret


def get_rsa_public_key():
    key_path = os.environ.get("RSA_PUBLIC_KEY_PATH")
    if not key_path:
        raise ValueError("RSA_PUBLIC_KEY_PATH environment variable is not set")
    with open(key_path, "r") as f:
        return f.read()


def create_token(user_id: int) -> str:
    secret = get_jwt_secret()
    payload = {
        "sub": str(user_id),
        "iat": int(time.time()),
        "exp": int(time.time()) + 3600
    }
    token = jwt.encode(payload, secret, algorithm=ALGORITHM)
    return token


def validate_token(token: str) -> dict:
    public_key = get_rsa_public_key()
    try:
        payload = jwt.decode(
            token,
            public_key,
            algorithms=[ALGORITHM],
            options={"require": ["exp", "iat"]}
        )
        return payload
    except jwt.ExpiredSignatureError:
        raise ValueError("Token has expired")
    except jwt.InvalidTokenError:
        raise ValueError("Invalid token")


def get_profile_cache_key(user_id: int) -> str:
    return f"{CACHE_PREFIX}{user_id}"


def get_user_profile(user_id: int) -> dict:
    cache_key = get_profile_cache_key(user_id)
    cached_data = cache.get(cache_key)
    if cached_data is not None:
        return cached_data

    profile = fetch_profile_from_db(user_id)
    if profile is None:
        return None

    cache.set(cache_key, profile, timeout=CACHE_TTL)
    return profile


def fetch_profile_from_db(user_id: int) -> dict:
    from django.contrib.auth import get_user_model
    User = get_user_model()
    try:
        user = User.objects.get(id=user_id)
        return {
            "id": user.id,
            "username": user.username,
            "email": user.email,
            "first_name": user.first_name,
            "last_name": user.last_name
        }
    except User.DoesNotExist:
        return None

import os
import hashlib
import boto3
from botocore.exceptions import ClientError
import urllib3


def get_s3_client():
    region = os.environ.get('AWS_REGION', 'us-east-1')
    http = urllib3.PoolManager()
    s3_client = boto3.client('s3', region_name=region)
    return s3_client


def calculate_file_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def upload_backup_to_s3(file_path, bucket_name, object_key):
    s3_client = get_s3_client()
    file_hash = calculate_file_hash(file_path)

    try:
        s3_client.upload_file(
            file_path, 
            bucket_name, 
            object_key,
            ExtraArgs={
                'Metadata': {
                    'x-amz-meta-hash': file_hash
                }
            }
        )
        print(f"Successfully uploaded {file_path} to s3://{bucket_name}/{object_key}")
        return True
    except ClientError as e:
        print(f"Error uploading file: {e}")
        return False


def verify_backup_integrity(file_path, remote_hash):
    local_hash = calculate_file_hash(file_path)
    if local_hash == remote_hash:
        return True
    return False

