from typing import Dict, Any

SECRET_KEY = os.environ.get('OAUTH_JWT_SECRET')
if not SECRET_KEY:
    raise ValueError("OAUTH_JWT_SECRET environment variable must be set")

def generate_state() -> str:
    """Generate a cryptographically secure state string."""
    return secrets.token_urlsafe(32)

def create_state_token(state: str, expiry_seconds: int = 300) -> str:
    """Create a JWT token for the OAuth state with expiry."""
    if not SECRET_KEY:
        raise ValueError("JWT secret key not configured")

    now = int(time.time())
    payload = {
        'state': state,
        'iat': now,
        'exp': now + expiry_seconds
    }
    try:
        token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
        return token
    except jwt.PyJWTError as e:
        raise RuntimeError(f"Failed to encode state token: {e}")

def verify_state_token(token: str) -> Dict[str, Any]:
    """Verify and decode the OAuth state token."""
    if not SECRET_KEY:
        raise ValueError("JWT secret key not configured")

    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        if 'state' not in payload:
            raise ValueError("Missing state in token payload")
        return payload
    except jwt.ExpiredSignatureError:
        raise ValueError("State token has expired")
    except jwt.InvalidTokenError as e:
        raise ValueError(f"Invalid state token: {e}")
