@app.route('/telemetry', methods=['POST'])
def handle_telemetry():
    if 'Authorization' not in request.headers:
        return jsonify({'error': 'Missing Authorization header'}), 401

    auth_header = request.headers['Authorization']
    if not auth_header.startswith('Signature '):
        return jsonify({'error': 'Invalid auth format'}), 401

    parts = auth_header.split(' ', 1)
    if len(parts) != 2:
        return jsonify({'error': 'Malformed signature'}), 401

    signature_b64 = parts[1]
    # In a real app, you'd parse the signature components properly
    # Here we assume the signature is the only part for simplicity
    try:
        import base64
        signature = base64.b64decode(signature_b64)
    except Exception:
        return jsonify({'error': 'Invalid signature encoding'}), 400

    payload = request.get_data(as_text=True)

    is_valid = verify_signature(payload, signature, public_key)

    if not is_valid:
        return jsonify({'error': 'Invalid signature'}), 403

    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        return jsonify({'error': 'Invalid JSON'}), 400

    return jsonify({'status': 'accepted', 'data': data}), 200

