class MetricsWorker:
    def __init__(self, api_key):
        self.api_key = api_key
        self.session = requests.Session()
        self.session.headers.update({
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}"
        })

    def send_batch(self, metrics):
        payload = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "data": metrics
        }
        for attempt in range(MAX_RETRIES):
            try:
                response = self.session.post(
                    METRICS_ENDPOINT,
                    json=payload,
                    timeout=REQUEST_TIMEOUT
                )
                response.raise_for_status()
                return True
            except requests.exceptions.RequestException as e:
                logger.error(f"Failed to send metrics (attempt {attempt + 1}): {e}")
                if attempt < MAX_RETRIES - 1:
                    time.sleep(2 ** attempt)
                else:
                    logger.critical("Max retries exceeded for metrics export")
                    return False
        return False

    def run(self):
        while True:
            try:
                current_metrics = self.collect_metrics()
                if current_metrics:
                    self.send_batch(current_metrics)
            except Exception as e:
                logger.exception("Unexpected error in metrics worker loop")
            time.sleep(60)

    def collect_metrics(self):
        return []

