import argparse
import os
import json
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend


def load_keyring(keyring_path):
    if not os.path.exists(keyring_path):
        return {}
    with open(keyring_path, 'r') as f:
        return json.load(f)


def save_keyring(keyring_path, keyring):
    with open(keyring_path, 'w') as f:
        json.dump(keyring, f, indent=4)


def generate_symmetric_key():
    return Fernet.generate_key()


def generate_asymmetric_key():
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
        backend=default_backend()
    )
    public_key = private_key.public_key()
    return private_key, public_key


def rotate_symmetric(keys, key_id, keyring_path):
    new_key = generate_symmetric_key()
    keys[key_id] = new_key.decode()
    save_keyring(keyring_path, keys)
    print(f"Rotated symmetric key: {key_id}")


def rotate_asymmetric(keys, key_id, keyring_path):
    private_key, public_key = generate_asymmetric_key()
    private_pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    )
    public_pem = public_key.public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo
    )
    keys[key_id] = {
        "private": private_pem.decode(),
        "public": public_pem.decode()
    }
    save_keyring(keyring_path, keys)
    print(f"Rotated asymmetric key: {key_id}")


def main():
    parser = argparse.ArgumentParser(description="Key Rotation Tool")
    parser.add_argument("--keyring", required=True, help="Path to the keyring file")
    parser.add_argument("--key-id", required=True, help="ID of the key to rotate")
    parser.add_argument("--type", required=True, choices=["symmetric", "asymmetric"], help="Type of key")
    args = parser.parse_args()

    keys = load_keyring(args.keyring)

    if args.type == "symmetric":
        rotate_symmetric(keys, args.key_id, args.keyring)
    elif args.type == "asymmetric":
        rotate_asymmetric(keys, args.key_id, args.keyring)


if __name__ == "__main__":
    main()

