import secrets
import hmac
import hashlib
from flask import request, g, abort
from functools import wraps


class CsrfTokenManager:
    SECRET_KEY = secrets.token_hex(32)
    TOKEN_LENGTH = 32

    @staticmethod
    def generate_token():
        token = secrets.token_hex(CsrfTokenManager.TOKEN_LENGTH)
        signature = hmac.new(
            CsrfTokenManager.SECRET_KEY.encode('utf-8'),
            token.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        return f"{token}.{signature}"

    @staticmethod
    def validate_token(token):
        if not token or '.' not in token:
            return False
        try:
            token_part, signature_part = token.rsplit('.', 1)
            expected_signature = hmac.new(
                CsrfTokenManager.SECRET_KEY.encode('utf-8'),
                token_part.encode('utf-8'),
                hashlib.sha256
            ).hexdigest()
            if not hmac.compare_digest(expected_signature, signature_part):
                return False
            return True
        except Exception:
            return False

    @staticmethod
    def csrf_protect(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if request.method in ('POST', 'PUT', 'DELETE', 'PATCH'):
                token = request.form.get('csrf_token') or request.headers.get('X-CSRFToken')
                if not token or not CsrfTokenManager.validate_token(token):
                    abort(403)
            return f(*args, **kwargs)
        return decorated_function

