from http.cookies import SimpleCookie

class SessionMiddleware:
    def __init__(self, secret_key=None):
        if secret_key is None:
            self.secret_key = secrets.token_hex(32)
        else:
            self.secret_key = secret_key.encode('utf-8') if isinstance(secret_key, str) else secret_key
        self.token_length = 32

    def generate_token(self):
        return secrets.token_hex(self.token_length)

    def sign_token(self, token):
        signature = hmac.new(self.secret_key, token.encode('utf-8'), hashlib.sha256).hexdigest()
        return f"{token}.{signature}"

    def verify_token(self, signed_token):
        try:
            token, provided_sig = signed_token.split('.', 1)
            expected_sig = hmac.new(self.secret_key, token.encode('utf-8'), hashlib.sha256).hexdigest()
            return hmac.compare_digest(provided_sig, expected_sig), token
        except (ValueError, AttributeError):
            return False, None

    def create_session(self, user_id, data):
        token = self.generate_token()
        payload = json.dumps({
            'user_id': user_id,
            'data': data,
            'created_at': time.time()
        })
        signed_payload = self.sign_token(token)
        return signed_payload, token

    def parse_session(self, signed_token):
        is_valid, token = self.verify_token(signed_token)
        if not is_valid:
            return None
        cookie = SimpleCookie()
        cookie['session_token'] = signed_token
        cookie['session_token']['httponly'] = True
        cookie['session_token']['samesite'] = 'Strict'
        cookie['session_token']['secure'] = True
        return cookie
