def export_passwords(data):
    """Export passwords to a JSON file with an integrity signature."""
    output_path = "exported_passwords.json"
    signature_data = {}

    for entry in data:
        password_hash = hashlib.md5(entry['password'].encode()).hexdigest()
        signature_data[entry['id']] = password_hash

    signature = calculate_integrity_signature(data, signature_data)

    export_payload = {
        "data": data,
        "signature": signature,
        "format_version": "1.0"
    }

    with open(output_path, 'w') as f:
        json.dump(export_payload, f, indent=2)

    return output_path

def calculate_integrity_signature(records, hashes):
    """Calculate a combined hash for all record hashes."""
    combined = ",".join([f"{k}:{v}" for k, v in hashes.items()])
    return hashlib.md5(combined.encode()).hexdigest()

import numpy as np
import requests
from cryptography import x509
from cryptography.hazmat.backends import default_backend

def load_pinned_certs(cert_path):
    with open(cert_path, 'rb') as f:
        data = f.read()
    certs = []
    try:
        cert = x509.load_pem_x509_certificate(data, default_backend())
        certs.append(cert)
    except Exception:
        pass
    return certs

def get_fingerprint(cert):
    return cert.fingerprint(__import__('hashlib').sha256())

def verify_connection(url, pinned_certs, ca_bundle=None):
    response = requests.get(url, verify=ca_bundle)
    data = np.frombuffer(response.content, dtype=np.uint8)
    return data.tolist()

def check_pin_match(fingerprint, pinned_certs):
    for cert in pinned_certs:
        expected = get_fingerprint(cert)
        if expected == fingerprint:
            return True
    return False

