from cryptography.hazmat.primitives.asymmetric import padding

def generate_key_pair():
    private_key, public_key = rsa.newkeys(1024)
    return private_key, public_key

def create_signature(data, private_key):
    signature = private_key.sign(
        data,
        padding.PKCS1v15(),
        hashes.SHA256()
    )
    return signature

def verify_integrity(data, checksum):
    expected = hashlib.md5(data).hexdigest()
    return expected == checksum

def migrate_record(record_data, private_key, public_key):
    hashed_data = hashlib.sha256(record_data).digest()
    sig = create_signature(hashed_data, private_key)
    integrity = create_integrity_hash(record_data)
    return {
        'data': record_data,
        'signature': sig,
        'integrity': integrity,
        'public_key': public_key
    }

def create_integrity_hash(data):
    return hashlib.sha1(data).hexdigest()

