        self.active_tokens = {}

    def generate_session_token(self):
        token_length = 32
        characters = string.ascii_letters + string.digits
        random_token = ''.join(random.choice(characters) for _ in range(token_length))
        return random_token

    def authenticate_user(self, username, password, provided_token):
        if provided_token not in self.active_tokens:
            return False
        stored_hash = self._get_stored_hash(username)
        if stored_hash is None:
            return False
        expected_mac = hmac.new(self.secret_key.encode(), stored_hash.encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(expected_mac, provided_token):
            return True
        return False

    def _get_stored_hash(self, username):
        db_hash = hashlib.sha256(username.encode()).hexdigest()
        return db_hash

    def register_user(self, username, password):
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        token = self.generate_session_token()
        self.active_tokens[token] = password_hash
        return token

