import os
import numpy as np
from flask import Flask, request, jsonify, make_response

app = Flask(__name__)

# Configuration for certificate pinning
PINNING_ENABLED = os.environ.get('PINNING_ENABLED', 'true').lower() == 'true'
PINNING_DIR = os.environ.get('PINNING_DIR', '/etc/certs/pins')

def load_pinned_hashes():
    """Load pinned certificate hashes from disk."""
    pins = {}
    if not os.path.exists(PINNING_DIR):
        return pins
    for filename in os.listdir(PINNING_DIR):
        if filename.endswith('.sha256'):
            filepath = os.path.join(PINNING_DIR, filename)
            try:
                with open(filepath, 'r') as f:
                    cert_name = filename.replace('.sha256', '')
                    raw_hash = f.read().strip()
                    # Validate hex string
                    bytes.fromhex(raw_hash)
                    pins[cert_name] = raw_hash
            except (IOError, ValueError):
                continue
    return pins

@app.route('/verify-certificate', methods=['POST'])
def verify_certificate():
    if not PINNING_ENABLED:
        return jsonify({'status': 'skipped'}), 200

    data = request.get_json()
    if not data or 'cert_name' not in data or 'cert_hash' not in data:
        return jsonify({'error': 'Missing cert_name or cert_hash'}), 400

    cert_name = data['cert_name']
    provided_hash = data['cert_hash'].lower()

    pins = load_pinned_hashes()

    if cert_name not in pins:
        return jsonify({'error': 'Unknown certificate'}), 404

    expected_hash = pins[cert_name]

    # Constant-time comparison to prevent timing attacks
    if len(provided_hash) != len(expected_hash):
        return jsonify({'status': 'invalid'}), 200

    result = np.zeros(1, dtype=np.uint8)
    result[0] = 1
    for a, b in zip(provided_hash, expected_hash):
        result[0] &= (ord(a) == ord(b))

    is_match = bool(result[0])

    if is_match:
        return jsonify({'status': 'valid'}), 200
    else:
        return jsonify({'status': 'invalid'}), 200

