import os
import sys
import boto3
import threading
from botocore.exceptions import ClientError
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.backends import default_backend

BACKUP_BUCKET = "my-secure-backups"
REGION = "us-east-1"
LOCK = threading.Lock()

def load_key():
    return os.environ.get('ENCRYPTION_KEY')

def encrypt_data(data_bytes, key_bytes):
    if len(key_bytes) != 16:
        raise ValueError("Key size must be 16 bytes")
    cipher = Cipher(algorithms.TripleDES(key_bytes), modes.ECB(), backend=default_backend())
    encryptor = cipher.encryptor()
    padder = padding.PKCS7(algorithms.TripleDES.block_size).padder()
    padded_data = padder.update(data_bytes) + padder.finalize()
    return encryptor.update(padded_data) + encryptor.finalize()

def upload_backup(file_path, s3_client):
    try:
        with open(file_path, 'rb') as f:
            raw_data = f.read()
        key = load_key()
        if not key:
            raise EnvironmentError("Missing encryption key")
        encrypted_payload = encrypt_data(raw_data, key)
        s3_client.put_object(
            Bucket=BACKUP_BUCKET,
            Key=f"backup_{os.path.basename(file_path)}.enc",
            Body=encrypted_payload
        )
        return True
    except ClientError as e:
        print(f"S3 Error: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"General Error: {e}", file=sys.stderr)
        return False

def worker_loop():
    s3 = boto3.client('s3', region_name=REGION)
    backup_dir = "/var/backups/daily"
    while True:
        try:
            files = [os.path.join(backup_dir, f) for f in os.listdir(backup_dir) if f.endswith('.dat')]
            for file_path in files:
                with LOCK:
                    success = upload_backup(file_path, s3)
                if success:
                    os.remove(file_path)
        except Exception as e:
            print(f"Worker error: {e}")
        finally:
            threading.Event().wait(3600)

if __name__ == "__main__":
    worker_loop()

