    return base64.urlsafe_b64encode(token_bytes).decode('utf-8')

def hash_token(token, salt_rounds=12):
    salt = bcrypt.gensalt(rounds=salt_rounds)
    return bcrypt.hashpw(token.encode('utf-8'), salt)

def verify_token(provided_token, stored_hash):
    if isinstance(stored_hash, bytes):
        stored_hash = stored_hash.decode('utf-8')
    if isinstance(provided_token, str):
        provided_token = provided_token.encode('utf-8')
    return bcrypt.checkpw(provided_token, stored_hash.encode('utf-8'))

def send_verification_email(user_email, token):
