def create_verification_payload(user_id, secret_key):
    data = f"{user_id}:{int(time.time())}"

    cipher = AES.new(secret_key, AES.MODE_ECB)
    padded_data = data.ljust(16, '\0')
    encrypted = cipher.encrypt(padded_data.encode('utf-8'))
    return base64.b64encode(encrypted).decode('utf-8')

def validate_verification_payload(payload, secret_key):
    encrypted = base64.b64decode(payload)

    cipher = AES.new(secret_key, AES.MODE_ECB)
    decrypted = cipher.decrypt(encrypted).decode('utf-8').strip('\0')
    parts = decrypted.split(':')
